content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Transportation Manager",
      "description": "Oversees transport operations, assigns routes, and evaluates performance."
    },
    {
      "name": "Transport Schedule",
      "description": "Plan outlining all delivery routes and assigned resources.",
      "attributes": [
        "Delivery Route"
      ]
    },
    {
      "name": "Delivery Route",
      "description": "Specific path assigned to a vehicle and driver for a delivery.",
      "attributes": [
        "Delivery Log",
        "Vehicle"
      ]
    },
    {
      "name": "Delivery Log",
      "description": "Record of trip details including times, stops, and cargo status."
    },
    {
      "name": "Vehicle",
      "description": "Transport unit used for deliveries.",
      "attributes": [
        "Capacity",
        "Maintenance Records"
      ]
    },
    {
      "name": "Capacity",
      "description": "Maximum load a vehicle can carry."
    },
    {
      "name": "Maintenance Records",
      "description": "Historical record of maintenance performed on a vehicle."
    },
    {
      "name": "Dispatcher",
      "description": "Coordinates routes, assigns vehicles, and monitors ongoing deliveries."
    },
    {
      "name": "Performance Report",
      "description": "Report summarizing delivery efficiency and performance metrics."
    },
    {
      "name": "Client",
      "description": "Company or entity requesting transportation services."
    },
    {
      "name": "Transport Request",
      "description": "Request from a client specifying cargo and destination details."
    },
    {
      "name": "Security Officer",
      "description": "Ensures cargo safety through inspection and escort operations."
    },
    {
      "name": "Cargo Escort",
      "description": "Security operation accompanying valuable cargo during transport.",
      "attributes": [
        "Vehicle"
      ]
    },
    {
      "name": "Cargo Inspection",
      "description": "Security check verifying cargo integrity before loading."
    },
    {
      "name": "Security Incident",
      "description": "Event or report describing a breach or safety issue during transport."
    },
    {
      "name": "Driver",
      "description": "Operates the vehicle to complete assigned delivery routes."
    },
    {
      "name": "Vehicle Inspection",
      "description": "Driver-conducted check of vehicle condition before departure."
    },
    {
      "name": "Maintenance Issue",
      "description": "Problem identified during inspection or operation requiring repair."
    },
    {
      "name": "Maintenance Technician",
      "description": "Performs vehicle maintenance and repairs."
    },
    {
      "name": "Maintenance Task",
      "description": "Scheduled or corrective maintenance action performed on a vehicle."
    }
  ]
}
```
